syntax = "proto3";

package roombook.v1;

service Rooms {
  rpc GetRoom(GetRoomRequest) returns (Room);
  rpc WatchAvailability(WatchAvailabilityRequest) returns (stream Availability);
}

message GetRoomRequest {
  int64 id = 1;
}

message Room {
  int64 id = 1;
  string name = 2;
  int32 capacity = 3;
  repeated string amenities = 4;
}

message WatchAvailabilityRequest {
  int64 room_id = 1;
  string date = 2;
}

message Availability {
  string starts_at = 1;
  string ends_at = 2;
  bool available = 3;
}
